cv &lt;- function(x, na.rm = TRUE){
  sd(x, na.rm = na.rm) / mean(x, na.rm = na.rm) * 100
  }

cv(dfrg$mg)

[1] 89.28828

confint &lt;- function(x, na.rm = TRUE, return = "inf") {
  n &lt;- length(na.omit(x))
  ttab &lt;- qt(0.975, n - 1)
  epm &lt;- sd(x, na.rm = na.rm) / sqrt(n)
  media &lt;- mean(x, na.rm = na.rm)
  if(return == "inf") {
    media - ttab * epm }
  else{
    media + ttab * epm
  }
}

confint(df$mg)

[1] 1.97624

